-- Move ServiceTitan reporting/sync implementations out of the exposed public API schema.
-- Public function names remain stable and execute as the caller.

create or replace function private.get_service_titan_customer_history(p_customer_id text) returns jsonb language plpgsql stable security definer set search_path='' as $$ begin if not public.has_permission_for_current_user('view_customers') then raise exception 'Customer permission required'; end if; return jsonb_build_object('customer',(select payload from public.service_titan_records where resource='customers' and external_id=p_customer_id limit 1),'locations',coalesce((select jsonb_agg(payload order by synced_at desc) from public.service_titan_records where resource='locations' and payload->>'customerId'=p_customer_id),'[]'::jsonb),'jobs',coalesce((select jsonb_agg(payload order by nullif(payload->>'completedOn','') desc nulls last) from public.service_titan_records where resource='jobs' and payload->>'customerId'=p_customer_id),'[]'::jsonb),'appointments',coalesce((select jsonb_agg(payload order by nullif(payload->>'start','') desc nulls last) from public.service_titan_records where resource='appointments' and payload->>'customerId'=p_customer_id),'[]'::jsonb),'invoices',coalesce((select jsonb_agg(payload order by nullif(payload->>'invoiceDate','') desc nulls last) from public.service_titan_records where resource='invoices' and coalesce(payload->'customer'->>'id',payload->>'customerId')=p_customer_id),'[]'::jsonb),'openBalance',coalesce((select sum(case when coalesce(payload->>'balance','') ~ '^-?[0-9]+(\.[0-9]+)?$' then (payload->>'balance')::numeric else 0 end) from public.service_titan_records where resource='invoices' and coalesce(payload->'customer'->>'id',payload->>'customerId')=p_customer_id),0),'lifetimeRevenue',coalesce((select sum(case when coalesce(payload->>'total','') ~ '^-?[0-9]+(\.[0-9]+)?$' then (payload->>'total')::numeric else 0 end) from public.service_titan_records where resource='invoices' and coalesce(payload->'customer'->>'id',payload->>'customerId')=p_customer_id),0)); end $$;
create or replace function public.get_service_titan_customer_history(p_customer_id text) returns jsonb language sql stable security invoker set search_path='' as $$ select private.get_service_titan_customer_history(p_customer_id) $$;

create or replace function private.service_titan_ar_aging(p_limit integer default 200) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_limit integer:=least(greatest(coalesce(p_limit,200),1),500); v_result jsonb; begin if not public.has_permission_for_current_user('view_accounting') then raise exception 'permission denied'; end if; select jsonb_build_object('summary',jsonb_build_object('current',coalesce(sum(balance) filter(where age_days<=0),0),'days1to30',coalesce(sum(balance) filter(where age_days between 1 and 30),0),'days31to60',coalesce(sum(balance) filter(where age_days between 31 and 60),0),'days61to90',coalesce(sum(balance) filter(where age_days between 61 and 90),0),'days90plus',coalesce(sum(balance) filter(where age_days>90),0),'totalOpen',coalesce(sum(balance),0),'openInvoices',count(*)),'invoices',coalesce(jsonb_agg(jsonb_build_object('externalId',external_id,'referenceNumber',reference_number,'customerId',customer_id,'customerName',customer_name,'invoiceDate',invoice_date,'dueDate',due_date,'ageDays',age_days,'total',total,'balance',balance,'jobId',job_id) order by age_days desc,balance desc) filter(where rn<=v_limit),'[]'::jsonb)) into v_result from (select x.*,row_number() over(order by age_days desc,balance desc) rn from (select r.external_id,r.payload->>'referenceNumber' reference_number,coalesce(r.payload->'customer'->>'id',r.payload->>'customerId') customer_id,coalesce(r.payload->'customer'->>'name',r.payload->>'customerName') customer_name,nullif(r.payload->>'invoiceDate','')::date invoice_date,nullif(r.payload->>'dueDate','')::date due_date,greatest(0,current_date-coalesce(nullif(r.payload->>'dueDate','')::date,nullif(r.payload->>'invoiceDate','')::date,current_date)) age_days,case when coalesce(r.payload->>'total','') ~ '^-?[0-9]+(\.[0-9]+)?$' then (r.payload->>'total')::numeric else 0 end total,case when coalesce(r.payload->>'balance','') ~ '^-?[0-9]+(\.[0-9]+)?$' then (r.payload->>'balance')::numeric else 0 end balance,coalesce(r.payload->'job'->>'id',r.payload->>'jobId') job_id from public.service_titan_records r where r.resource='invoices' and case when coalesce(r.payload->>'balance','') ~ '^-?[0-9]+(\.[0-9]+)?$' then (r.payload->>'balance')::numeric else 0 end>0)x)q; return coalesce(v_result,jsonb_build_object('summary',jsonb_build_object('current',0,'days1to30',0,'days31to60',0,'days61to90',0,'days90plus',0,'totalOpen',0,'openInvoices',0),'invoices','[]'::jsonb)); end $$;
create or replace function public.service_titan_ar_aging(p_limit integer default 200) returns jsonb language sql security invoker set search_path='' as $$ select private.service_titan_ar_aging(p_limit) $$;

create or replace function private.service_titan_customer_directory(p_limit integer default 100,p_search text default null) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_limit integer:=least(greatest(coalesce(p_limit,100),1),250); v_search text:=nullif(btrim(coalesce(p_search,'')),''); v_result jsonb; begin if not public.has_permission_for_current_user('view_customers') then raise exception 'permission denied'; end if; select coalesce(jsonb_agg(x.row_data order by x.sort_name,x.external_id),'[]'::jsonb) into v_result from (select jsonb_build_object('externalId',c.external_id,'name',c.payload->>'name','type',c.payload->>'type','active',c.payload->'active','balance',case when coalesce(c.payload->>'balance','') ~ '^-?[0-9]+(\.[0-9]+)?$' then (c.payload->>'balance')::numeric else 0 end,'address',c.payload->'address','jobCount',coalesce(j.job_count,0),'lastJobAt',j.last_job_at,'syncedAt',c.synced_at) row_data,lower(coalesce(c.payload->>'name','')) sort_name,c.external_id from public.service_titan_records c left join lateral(select count(*)::integer job_count,max(nullif(jr.payload->>'completedOn','')::timestamptz) last_job_at from public.service_titan_records jr where jr.resource='jobs' and jr.payload->>'customerId'=c.external_id)j on true where c.resource='customers' and (v_search is null or c.payload->>'name' ilike '%'||v_search||'%' or c.external_id ilike '%'||v_search||'%' or c.payload->'address'->>'street' ilike '%'||v_search||'%' or c.payload->'address'->>'city' ilike '%'||v_search||'%') order by lower(coalesce(c.payload->>'name','')),c.external_id limit v_limit)x; return v_result; end $$;
create or replace function public.service_titan_customer_directory(p_limit integer default 100,p_search text default null) returns jsonb language sql security invoker set search_path='' as $$ select private.service_titan_customer_directory(p_limit,p_search) $$;

create or replace function private.service_titan_recall_snapshot(p_days integer default 90) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare v_days integer:=least(greatest(coalesce(p_days,90),1),365); v_since timestamptz:=now()-make_interval(days=>v_days); v_result jsonb; begin if not public.has_permission_for_current_user('view_team') then raise exception 'permission denied'; end if; select jsonb_build_object('days',v_days,'recalls',count(*),'records',coalesce(jsonb_agg(jsonb_build_object('jobId',j.external_id,'jobNumber',j.payload->>'jobNumber','recallForId',j.payload->>'recallForId','summary',j.payload->>'summary','completedOn',j.payload->>'completedOn','soldById',j.payload->>'soldById') order by coalesce(nullif(j.payload->>'completedOn','')::timestamptz,nullif(j.payload->>'createdOn','')::timestamptz) desc),'[]'::jsonb)) into v_result from public.service_titan_records j where j.resource='jobs' and nullif(j.payload->>'recallForId','') is not null and coalesce(nullif(j.payload->>'completedOn','')::timestamptz,nullif(j.payload->>'createdOn','')::timestamptz)>=v_since; return coalesce(v_result,jsonb_build_object('days',v_days,'recalls',0,'records','[]'::jsonb)); end $$;
create or replace function public.service_titan_recall_snapshot(p_days integer default 90) returns jsonb language sql stable security invoker set search_path='' as $$ select private.service_titan_recall_snapshot(p_days) $$;

create or replace function private.service_titan_sync_status_summary() returns jsonb language plpgsql security definer set search_path='' as $$ declare v_counts jsonb; v_total bigint; begin if not public.has_permission_for_current_user('manage_permissions') then raise exception 'Owner permission required'; end if; select coalesce(jsonb_object_agg(resource,record_count),'{}'::jsonb),coalesce(sum(record_count),0) into v_counts,v_total from (select resource,count(*)::bigint record_count from public.service_titan_records where resource in('technicians','business_units','customers','locations','jobs','appointments','invoices','payments','memberships') group by resource)s; return jsonb_build_object('counts',v_counts,'totalCached',v_total); end $$;
create or replace function public.service_titan_sync_status_summary() returns jsonb language sql security invoker set search_path='' as $$ select private.service_titan_sync_status_summary() $$;

create or replace function private.service_titan_technician_sales_funnel(p_days integer default 30) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare v_days integer:=least(greatest(coalesce(p_days,30),1),365); v_since timestamptz:=now()-make_interval(days=>v_days); v_result jsonb; begin if not public.has_permission_for_current_user('view_team') then raise exception 'permission denied'; end if; select coalesce(jsonb_agg(x.row_data order by x.sold_revenue desc,x.technician_name),'[]'::jsonb) into v_result from (select coalesce(nullif(t.payload->>'name',''),concat_ws(' ',t.payload->>'firstName',t.payload->>'lastName')) technician_name,coalesce(sum(case when coalesce(j.payload->>'total','') ~ '^-?[0-9]+(\.[0-9]+)?$' then (j.payload->>'total')::numeric else 0 end),0) sold_revenue,jsonb_build_object('technicianId',t.external_id,'name',coalesce(nullif(t.payload->>'name',''),concat_ws(' ',t.payload->>'firstName',t.payload->>'lastName')),'jobsWithEstimate',count(j.external_id) filter(where jsonb_array_length(coalesce(j.payload->'estimateIds','[]'::jsonb))>0),'soldJobs',count(j.external_id) filter(where nullif(j.payload->>'soldById','') is not null),'completedSoldJobs',count(j.external_id) filter(where nullif(j.payload->>'soldById','') is not null and nullif(j.payload->>'completedOn','') is not null),'soldRevenue',coalesce(sum(case when coalesce(j.payload->>'total','') ~ '^-?[0-9]+(\.[0-9]+)?$' then (j.payload->>'total')::numeric else 0 end),0),'averageSoldTicket',coalesce(avg(case when coalesce(j.payload->>'total','') ~ '^-?[0-9]+(\.[0-9]+)?$' then (j.payload->>'total')::numeric else null end),0),'recallJobs',count(j.external_id) filter(where nullif(j.payload->>'recallForId','') is not null)) row_data from public.service_titan_records t left join public.service_titan_records j on j.resource='jobs' and j.payload->>'soldById'=t.external_id and coalesce(nullif(j.payload->>'completedOn','')::timestamptz,nullif(j.payload->>'createdOn','')::timestamptz)>=v_since where t.resource='technicians' group by t.external_id,t.payload)x; return v_result; end $$;
create or replace function public.service_titan_technician_sales_funnel(p_days integer default 30) returns jsonb language sql stable security invoker set search_path='' as $$ select private.service_titan_technician_sales_funnel(p_days) $$;

create or replace function private.service_titan_technician_sales_performance(p_days integer default 30) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_days integer:=least(greatest(coalesce(p_days,30),1),365); v_since timestamptz:=now()-make_interval(days=>v_days); v_result jsonb; begin if not public.has_permission_for_current_user('view_team') then raise exception 'permission denied'; end if; select coalesce(jsonb_agg(row_data order by revenue desc,technician_name),'[]'::jsonb) into v_result from (select jsonb_build_object('technicianId',t.external_id,'name',coalesce(nullif(t.payload->>'name',''),concat_ws(' ',t.payload->>'firstName',t.payload->>'lastName')),'active',t.payload->'active','businessUnitId',t.payload->>'businessUnitId','soldJobs',count(j.external_id),'completedSoldJobs',count(j.external_id) filter(where nullif(j.payload->>'completedOn','') is not null),'revenue',coalesce(sum(case when coalesce(j.payload->>'total','') ~ '^-?[0-9]+(\.[0-9]+)?$' then (j.payload->>'total')::numeric else 0 end),0),'averageTicket',coalesce(avg(case when coalesce(j.payload->>'total','') ~ '^-?[0-9]+(\.[0-9]+)?$' then (j.payload->>'total')::numeric else null end),0),'lastSoldJobAt',max(nullif(j.payload->>'completedOn','')::timestamptz)) row_data,coalesce(nullif(t.payload->>'name',''),concat_ws(' ',t.payload->>'firstName',t.payload->>'lastName')) technician_name,coalesce(sum(case when coalesce(j.payload->>'total','') ~ '^-?[0-9]+(\.[0-9]+)?$' then (j.payload->>'total')::numeric else 0 end),0) revenue from public.service_titan_records t left join public.service_titan_records j on j.resource='jobs' and j.payload->>'soldById'=t.external_id and coalesce(nullif(j.payload->>'completedOn','')::timestamptz,nullif(j.payload->>'createdOn','')::timestamptz)>=v_since where t.resource='technicians' group by t.external_id,t.payload)s; return v_result; end $$;
create or replace function public.service_titan_technician_sales_performance(p_days integer default 30) returns jsonb language sql security invoker set search_path='' as $$ select private.service_titan_technician_sales_performance(p_days) $$;

create or replace function private.service_titan_technician_productivity(p_days integer default 30) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_since timestamptz:=now()-make_interval(days=>greatest(1,least(coalesce(p_days,30),365))); v_result jsonb; begin if not public.has_permission_for_current_user('view_team') then raise exception 'Team permission required'; end if; with techs as (select external_id technician_id,coalesce(nullif(payload->>'name',''),nullif(payload->>'displayName',''),'Technician '||external_id) technician_name from public.service_titan_records where resource='technicians'),ts as (select payload->>'technicianId' technician_id,payload->>'jobId' job_id,case when coalesce(payload->>'dispatchedOn','') ~ '^\d{4}-\d{2}-\d{2}T' then (payload->>'dispatchedOn')::timestamptz end dispatched_on,case when coalesce(payload->>'arrivedOn','') ~ '^\d{4}-\d{2}-\d{2}T' then (payload->>'arrivedOn')::timestamptz end arrived_on,case when coalesce(payload->>'doneOn','') ~ '^\d{4}-\d{2}-\d{2}T' then (payload->>'doneOn')::timestamptz end done_on from public.service_titan_records where resource='job_timesheets' and coalesce(payload->>'active','true')<>'false'),splits as (select payload->>'technicianId' technician_id,payload->>'jobId' job_id,case when coalesce(payload->>'split','') ~ '^-?[0-9]+(\.[0-9]+)?$' then (payload->>'split')::numeric else 0 end split from public.service_titan_records where resource='job_splits' and coalesce(payload->>'active','true')<>'false'),jobs as (select external_id job_id,case when coalesce(payload->>'total','') ~ '^-?[0-9]+(\.[0-9]+)?$' then (payload->>'total')::numeric else 0 end total,case when coalesce(payload->>'completedOn','') ~ '^\d{4}-\d{2}-\d{2}T' then (payload->>'completedOn')::timestamptz end completed_on from public.service_titan_records where resource='jobs'),agg as (select t.technician_id,t.technician_name,count(distinct ts.job_id) filter(where ts.done_on>=v_since)::int jobs_completed,round(coalesce(sum(extract(epoch from(ts.done_on-ts.arrived_on))/3600.0) filter(where ts.done_on>=v_since and ts.arrived_on is not null and ts.done_on>=ts.arrived_on),0)::numeric,2) onsite_hours,round(coalesce(sum(extract(epoch from(ts.arrived_on-ts.dispatched_on))/3600.0) filter(where ts.done_on>=v_since and ts.dispatched_on is not null and ts.arrived_on is not null and ts.arrived_on>=ts.dispatched_on),0)::numeric,2) dispatch_to_arrival_hours,round(coalesce(sum(j.total*case when s.split>1 then s.split/100.0 else s.split end) filter(where j.completed_on>=v_since),0),2) attributed_revenue from techs t left join ts on ts.technician_id=t.technician_id left join jobs j on j.job_id=ts.job_id left join splits s on s.job_id=ts.job_id and s.technician_id=t.technician_id group by t.technician_id,t.technician_name) select jsonb_build_object('days',greatest(1,least(coalesce(p_days,30),365)),'since',v_since,'timesheetRecords',(select count(*) from public.service_titan_records where resource='job_timesheets'),'splitRecords',(select count(*) from public.service_titan_records where resource='job_splits'),'technicians',coalesce(jsonb_agg(jsonb_build_object('technicianId',technician_id,'name',technician_name,'jobsCompleted',jobs_completed,'onsiteHours',onsite_hours,'dispatchToArrivalHours',dispatch_to_arrival_hours,'attributedRevenue',attributed_revenue,'revenuePerOnsiteHour',case when onsite_hours>0 then round(attributed_revenue/onsite_hours,2) else 0 end) order by attributed_revenue desc),'[]'::jsonb)) into v_result from agg; return v_result; end $$;
create or replace function public.service_titan_technician_productivity(p_days integer default 30) returns jsonb language sql security invoker set search_path='' as $$ select private.service_titan_technician_productivity(p_days) $$;

create or replace function private.refresh_service_titan_customer_mapping_candidates() returns jsonb language plpgsql security definer set search_path='' as $$ declare v_count integer:=0; begin if not public.has_permission_for_current_user('manage_permissions') then raise exception 'Owner permission required'; end if; insert into public.service_titan_record_mappings(resource,external_id,local_table,local_id,match_status,match_method,confidence,updated_at) select 'customers',r.external_id,'customers',c.id,case when count(*) over(partition by r.external_id)=1 then 'candidate' else 'conflict' end,'normalized_email_or_phone',case when lower(nullif(r.payload->>'email',''))=lower(nullif(c.email,'')) and regexp_replace(coalesce(r.payload->>'phone',''),'\D','','g')=regexp_replace(coalesce(c.phone,''),'\D','','g') then 0.99 else 0.90 end,now() from public.service_titan_records r join public.customers c on (nullif(r.payload->>'email','') is not null and lower(r.payload->>'email')=lower(coalesce(c.email,''))) or (length(regexp_replace(coalesce(r.payload->>'phone',''),'\D','','g'))>=10 and regexp_replace(coalesce(r.payload->>'phone',''),'\D','','g')=regexp_replace(coalesce(c.phone,''),'\D','','g')) where r.resource='customers' on conflict(resource,external_id,local_table) do update set local_id=excluded.local_id,match_status=excluded.match_status,match_method=excluded.match_method,confidence=excluded.confidence,updated_at=now() where public.service_titan_record_mappings.match_status in('unmatched','candidate','conflict'); get diagnostics v_count=row_count; insert into public.service_titan_record_mappings(resource,external_id,local_table,match_status,updated_at) select 'customers',r.external_id,'customers','unmatched',now() from public.service_titan_records r where r.resource='customers' and not exists(select 1 from public.service_titan_record_mappings m where m.resource='customers' and m.external_id=r.external_id and m.local_table='customers') on conflict do nothing; return jsonb_build_object('candidatesRefreshed',v_count); end $$;
create or replace function public.refresh_service_titan_customer_mapping_candidates() returns jsonb language sql security invoker set search_path='' as $$ select private.refresh_service_titan_customer_mapping_candidates() $$;

create or replace function private.upsert_service_titan_resource(p_resource text,p_records jsonb,p_environment text,p_tenant_id text) returns jsonb language plpgsql security definer set search_path='' set statement_timeout='20s' as $$ declare v_seen integer:=0;v_upserted integer:=0;v_run_id uuid; begin if not public.has_permission_for_current_user('manage_permissions') then raise exception 'Owner permission required'; end if; if p_resource not in('technicians','business_units','customers','locations','jobs','appointments','invoices','payments','memberships','job_timesheets','job_splits','pricebook_categories','pricebook_services','pricebook_materials','pricebook_equipment') then raise exception 'Unsupported ServiceTitan resource'; end if; if p_environment not in('integration','production') then raise exception 'Invalid ServiceTitan environment'; end if; if jsonb_typeof(p_records)<>'array' then raise exception 'ServiceTitan records must be a JSON array'; end if; select count(*) into v_seen from jsonb_array_elements(p_records); insert into public.service_titan_sync_runs(resource,status,requested_by) values(p_resource,'running',auth.uid()) returning id into v_run_id; with incoming as(select value item from jsonb_array_elements(p_records) where nullif(value->>'id','') is not null),upserted as(insert into public.service_titan_records(resource,external_id,payload,external_modified_at,synced_at) select p_resource,item->>'id',item,case when coalesce(item->>'modifiedOn','') ~ '^\d{4}-\d{2}-\d{2}T' then (item->>'modifiedOn')::timestamptz else null end,now() from incoming on conflict(resource,external_id) do update set payload=excluded.payload,external_modified_at=excluded.external_modified_at,synced_at=excluded.synced_at returning 1) select count(*) into v_upserted from upserted; insert into public.service_titan_integration_state(singleton,environment,tenant_id,last_successful_sync,last_error,updated_at) values(true,p_environment,p_tenant_id,now(),null,now()) on conflict(singleton) do update set environment=excluded.environment,tenant_id=excluded.tenant_id,last_successful_sync=excluded.last_successful_sync,last_error=null,updated_at=now(); update public.service_titan_sync_runs set status='success',records_seen=v_seen,records_upserted=v_upserted,completed_at=now() where id=v_run_id; return jsonb_build_object('runId',v_run_id,'resource',p_resource,'seen',v_seen,'upserted',v_upserted); end $$;
create or replace function public.upsert_service_titan_resource(p_resource text,p_records jsonb,p_environment text,p_tenant_id text) returns jsonb language sql security invoker set search_path='' as $$ select private.upsert_service_titan_resource(p_resource,p_records,p_environment,p_tenant_id) $$;

